async function issueInvitations(
  actor: Actor,
  orgId: OrgId,
  invites: readonly { readonly email: string; readonly role: Role }[],
  replacing: Invitation | null,
): Promise<readonly Invitation[]> {
  const verdict = await consumeRateLimit(orgId, INVITE_BUCKET, invites.length);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);

  const pending = (await invitationRepo.listPendingInvitations(orgId)).filter(
    (row) => row.id !== replacing?.id,
  );
  const pendingEmails = new Set(pending.map((row) => normalizeEmail(row.email)));
  const batchEmails = new Set<string>();

  for (const invite of invites) {
    const email = normalizeEmail(invite.email);

    if (batchEmails.has(email)) {
      throw new Error(`${invite.email} is listed more than once in this batch`);
    }
    batchEmails.add(email);

    if (pendingEmails.has(email)) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
    if ((await memberRepo.findLiveMemberByEmail(orgId, email)) !== null) {
      throw new Error(`${invite.email} is already a member of this organization`);
    }
  }

  const seatsUsed =
    (await memberRepo.countActiveMembers(orgId)) + pending.length;

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, invites.length)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  if (replacing) {
    await invitationRepo.revokeInvitation(orgId, replacing.id);
  }

  const invitations: Invitation[] = [];

  for (const invite of invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      {
        orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/** Addresses are compared without regard to letter case. */
function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 * The token alone is not enough, though — only the account the invitation was
 * addressed to may use it.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (org === null || org.archivedAt !== null) {
    throw new Error("That invitation belongs to a workspace that has been deleted");
  }

  const user = await userRepo.findUserById(userId);
  if (user === null || normalizeEmail(user.email) !== normalizeEmail(invitation.email)) {
    throw new Error("That invitation was sent to a different email address");
  }

  const now = toIsoTimestamp(new Date());
  const claimed = await invitationRepo.claimInvitation(
    invitation.orgId,
    invitation.id,
    now,
  );
  if (claimed === null) {
    throw new Error("That invitation has already been accepted");
  }

  const previous = await memberRepo.findMemberIncludingArchived(
    invitation.orgId,
    userId,
  );

  // Already a live member: the invitation is used up, but there is no second
  // membership and nothing joined.
  if (previous && previous.archivedAt === null) return previous;

  // A former member comes back on their old row rather than a second one.
  const member = previous
    ? await memberRepo.reactivateMember(
        invitation.orgId,
        previous.id,
        invitation.role,
        invitation.invitedBy,
        now,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately. An
 * expired invitation can be re-sent — that is the usual reason to.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );
  if (previous.acceptedAt !== null || previous.revokedAt !== null) {
    throw new NotFoundError("Invitation", invitationId);
  }

  const [invitation] = await issueInvitations(
    actor,
    actor.orgId,
    [{ email: previous.email, role: previous.role }],
    previous,
  );

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}
