const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let offUsage: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  offUsage = registerUsageListeners();
});

afterAll(() => {
  offUsage();
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
});

async function makeUser(email: string): Promise<UserId> {
  const user = await userRepo.insertUser({ email, name: email, passwordHash: "seed" });
  return user.id;
}

/** Sends an invitation through the service and returns the raw token minted for it. */
async function inviteWithToken(
  tenant: Tenant,
  email: string,
  role: "admin" | "member" | "viewer" = "member",
) {
  const token = `${hashToken(email + Math.random())}${"x".repeat(32)}`.slice(0, 40);
  const invitation = await invitationRepo.insertInvitation(
    tenant.org.id,
    { orgId: tenant.org.id, email, role, expiresInDays: 14 },
    tenant.userIds.admin,
    hashToken(token),
  );
  return { invitation, token };
}

describe("invitation lifecycle", () => {
  it("is valid for 14 days from the moment it is sent", async () => {
    const tenant = await createTenant("life-expiry", "growth");
    const before = Date.now();
    const invitation = await invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "someone@life-expiry.test",
      role: "member",
    });

    const validFor = Date.parse(invitation.expiresAt) - Date.parse(invitation.createdAt);
    expect(validFor).toBe(14 * DAY_MS);
    expect(Date.parse(invitation.createdAt)).toBeGreaterThanOrEqual(before - 1);
  });

  it("counts only pending invitations against the seats", async () => {
    const tenant = await createTenant("life-seats", "free");
    // Free plan: 3 seats. Remove the viewer and the member so two seats are free... (4 seeded).
    for (const role of ["viewer", "member", "admin"] as const) {
      const row = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
      if (!row) throw new Error("missing member");
      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: row.id,
      });
    }
    // Owner only: two seats free.
    const [first, second] = await invitationService.inviteMembers(tenant.actors.owner, {
      orgId: tenant.org.id,
      invites: [
        { email: "one@life-seats.test", role: "member" },
        { email: "two@life-seats.test", role: "member" },
      ],
    });
    await expect(
      invitationService.inviteMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        email: "three@life-seats.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    // Revoking frees a seat at once.
    await invitationService.revokeInvitation(tenant.actors.owner, first!.id);
    await expect(
      invitationService.inviteMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        email: "three@life-seats.test",
        role: "member",
      }),
    ).resolves.toBeDefined();

    // Expiry frees a seat at once too.
    vi.useFakeTimers();
    vi.setSystemTime(Date.parse(second!.expiresAt) + 1_000);
    await expect(invitationRepo.countPendingInvitations(tenant.org.id)).resolves.toBe(0);
    await expect(invitationRepo.listPendingInvitations(tenant.org.id)).resolves.toHaveLength(0);
  });

  it("refuses duplicates, members and repeated addresses in a batch, ignoring case", async () => {
    const tenant = await createTenant("life-dupes", "growth");
    await invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "Dupe@life-dupes.test",
      role: "member",
    });

    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "dupe@LIFE-dupes.test",
        role: "member",
      }),
    ).rejects.toThrow();

    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "Member@life-dupes.test",
        role: "member",
      }),
    ).rejects.toThrow();

    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "fresh@life-dupes.test", role: "member" },
          { email: "Fresh@life-dupes.test", role: "viewer" },
        ],
      }),
    ).rejects.toThrow();

    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.email)).toEqual(["Dupe@life-dupes.test"]);
  });

  it("allows inviting an address whose earlier invitation was revoked or expired", async () => {
    const tenant = await createTenant("life-reinvite", "growth");
    const first = await invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "again@life-reinvite.test",
      role: "member",
    });
    await invitationService.revokeInvitation(tenant.actors.admin, first.id);

    const second = await invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "again@life-reinvite.test",
      role: "member",
    });

    vi.useFakeTimers();
    vi.setSystemTime(Date.parse(second.expiresAt) + 1_000);
    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "again@life-reinvite.test",
        role: "member",
      }),
    ).resolves.toBeDefined();
  });

  it("lets only the addressee accept, and only once", async () => {
    const tenant = await createTenant("life-accept", "growth");
    const { invitation, token } = await inviteWithToken(
      tenant,
      "Invitee@life-accept.test",
      "admin",
    );
    const intruder = await makeUser("intruder@life-accept.test");
    const invitee = await makeUser("invitee@life-accept.test");

    await expect(
      invitationService.acceptInvitation(intruder, { token }),
    ).rejects.toThrow();
    await expect(memberRepo.findMember(tenant.org.id, intruder)).resolves.toBeNull();
    await expect(
      invitationRepo.findInvitationByTokenHash(hashToken(token)),
    ).resolves.toMatchObject({ acceptedAt: null });

    const member = await invitationService.acceptInvitation(invitee, { token });
    expect(member).toMatchObject({ role: "admin", status: "active", invitedBy: tenant.userIds.admin });

    // Full member at once: can act, is listed, takes a seat.
    await expect(memberService.resolveActor(invitee, tenant.org.id)).resolves.toMatchObject({
      role: "admin",
    });
    const listed = await memberRepo.listMembers({
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
    });
    expect(listed.items.some((row) => row.userId === invitee)).toBe(true);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(5);
    await expect(usageRepo.getUsage(tenant.org.id)).resolves.toMatchObject({ seatsUsed: 5 });

    await expect(
      invitationService.acceptInvitation(invitee, { token }),
    ).rejects.toThrow(/already been accepted/);
    expect(invitation.id).toBeDefined();
  });

  it("refuses an invitation to a deleted workspace", async () => {
    const tenant = await createTenant("life-deleted", "growth");
    const { token } = await inviteWithToken(tenant, "late@life-deleted.test");
    const user = await makeUser("late@life-deleted.test");

    await organizationService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    await expect(invitationService.acceptInvitation(user, { token })).rejects.toThrow();
    await expect(memberRepo.findMember(tenant.org.id, user)).resolves.toBeNull();
  });

  it("brings a former member back on their old row", async () => {
    const tenant = await createTenant("life-rejoin", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    const before = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!before) throw new Error("missing member");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: before.id,
    });
    await expect(usageRepo.getUsage(tenant.org.id)).resolves.toMatchObject({ seatsUsed: 3 });

    // A former member's address can be invited again.
    const { token } = await inviteWithToken(tenant, `viewer@life-rejoin.test`, "admin");
    const rejoined = await invitationService.acceptInvitation(tenant.userIds.viewer, { token });

    expect(rejoined.id).toBe(before.id);
    expect(rejoined).toMatchObject({
      role: "admin",
      status: "active",
      archivedAt: null,
      invitedBy: tenant.userIds.admin,
    });
    expect(rejoined.joinedAt).not.toBe(before.joinedAt);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(4);
    await expect(usageRepo.getUsage(tenant.org.id)).resolves.toMatchObject({ seatsUsed: 4 });
    await expect(memberService.resolveActor(tenant.userIds.viewer, tenant.org.id)).resolves.toMatchObject({
      role: "admin",
    });
  });

  it("re-sends with the same address and role, also after expiry", async () => {
    const tenant = await createTenant("life-resend", "growth");
    const original = await invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "resend@life-resend.test",
      role: "viewer",
    });

    vi.useFakeTimers();
    vi.setSystemTime(Date.parse(original.expiresAt) + DAY_MS);
    const resent = await invitationService.resendInvitation(tenant.actors.admin, original.id);

    expect(resent.id).not.toBe(original.id);
    expect(resent).toMatchObject({ email: "resend@life-resend.test", role: "viewer" });
    expect(Date.parse(resent.expiresAt) - Date.now()).toBe(14 * DAY_MS);
    await expect(
      invitationRepo.findInvitationById(tenant.org.id, original.id),
    ).resolves.toMatchObject({ revokedAt: expect.any(String) });
    await expect(invitationRepo.listPendingInvitations(tenant.org.id)).resolves.toHaveLength(1);
  });

  it("stops notifications, digests and default sessions for a removed member only", async () => {
    const tenant = await createTenant("life-removed", "growth");
    const other = await createTenant("life-removed-other", "growth");
    const leaver = tenant.userIds.member;

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: leaver,
      kind: "issue_assigned",
      inApp: true,
      email: true,
      digestOnly: true,
    });
    await memberRepo.insertMember(other.org.id, leaver, "member", null);

    const now = new Date(Date.now() + 30 * DAY_MS).toISOString();
    for (const hash of ["s-here", "s-there", "s-none"]) {
      await sessionRepo.createSession(leaver, hash, now as never);
    }
    const setOrg = (hash: string, orgId: string | null) =>
      getDb()
        .update(sessions)
        .set({ activeOrgId: orgId })
        .where(eq(sessions.tokenHash, hash))
        .run();
    setOrg("s-here", tenant.org.id);
    setOrg("s-there", other.org.id);

    await expect(listDigestRecipients(tenant.org.id)).resolves.toContain(leaver);

    const row = await memberRepo.findMember(tenant.org.id, leaver);
    if (!row) throw new Error("missing member");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: row.id,
    });

    const payload = { title: "t", body: "b", href: "/x", actorId: null };
    await expect(notify(tenant.org.id, "issue_assigned", [leaver], payload)).resolves.toHaveLength(0);
    await expect(listDigestRecipients(tenant.org.id)).resolves.not.toContain(leaver);

    const activeOrg = async (hash: string) =>
      (await sessionRepo.findSessionByTokenHash(hash))?.activeOrgId ?? null;
    await expect(activeOrg("s-here")).resolves.toBeNull();
    await expect(activeOrg("s-there")).resolves.toBe(other.org.id);

    // Rejoining restores notifications.
    const { token } = await inviteWithToken(tenant, `member@life-removed.test`);
    await invitationService.acceptInvitation(leaver, { token });
    await expect(notify(tenant.org.id, "issue_assigned", [leaver], payload)).resolves.toHaveLength(1);
    await expect(listDigestRecipients(tenant.org.id)).resolves.toContain(leaver);
  });

  it("stops every session defaulting to a deleted workspace", async () => {
    const tenant = await createTenant("life-org-deleted", "growth");
    const other = await createTenant("life-org-kept", "growth");
    const expiry = new Date(Date.now() + 30 * DAY_MS).toISOString();

    await sessionRepo.createSession(tenant.userIds.owner, "d-owner", expiry as never);
    await sessionRepo.createSession(tenant.userIds.admin, "d-admin", expiry as never);
    await sessionRepo.createSession(other.userIds.owner, "d-other", expiry as never);
    for (const [hash, orgId] of [
      ["d-owner", tenant.org.id],
      ["d-admin", tenant.org.id],
      ["d-other", other.org.id],
    ] as const) {
      getDb().update(sessions).set({ activeOrgId: orgId }).where(eq(sessions.tokenHash, hash)).run();
    }

    await organizationService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const activeOrg = async (hash: string) =>
      (await sessionRepo.findSessionByTokenHash(hash))?.activeOrgId ?? null;
    await expect(activeOrg("d-owner")).resolves.toBeNull();
    await expect(activeOrg("d-admin")).resolves.toBeNull();
    await expect(activeOrg("d-other")).resolves.toBe(other.org.id);

    // listNotifications stays reachable for the surviving org.
    await expect(
      listNotifications(other.actors.owner, {
        orgId: other.org.id,
        recipientId: other.userIds.owner,
        unreadOnly: false,
        limit: 5,
        cursor: null,
      }),
    ).resolves.toBeDefined();
  });
});

