      invitedBy: tenant.userIds.admin,
    });
    expect(rejoined.joinedAt).not.toBe(before.joinedAt);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(4);
    await expect(usageRepo.getUsage(tenant.org.id)).resolves.toMatchObject({ seatsUsed: 4 });
    await expect(memberService.resolveActor(tenant.userIds.viewer, tenant.org.id)).resolves.toMatchObject({
      role: "admin",
    });
  });

  it("re-sends with the same address and role, also after expiry", async () => {
    const tenant = await createTenant("life-resend", "growth");
    const original = await invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "resend@life-resend.test",
      role: "viewer",
    });

    vi.useFakeTimers();
    vi.setSystemTime(Date.parse(original.expiresAt) + DAY_MS);
    const resent = await invitationService.resendInvitation(tenant.actors.admin, original.id);

    expect(resent.id).not.toBe(original.id);
    expect(resent).toMatchObject({ email: "resend@life-resend.test", role: "viewer" });
    expect(Date.parse(resent.expiresAt) - Date.now()).toBe(14 * DAY_MS);
    await expect(
      invitationRepo.findInvitationById(tenant.org.id, original.id),
    ).resolves.toMatchObject({ revokedAt: expect.any(String) });
    await expect(invitationRepo.listPendingInvitations(tenant.org.id)).resolves.toHaveLength(1);
  });

  it("stops notifications, digests and default sessions for a removed member only", async () => {
    const tenant = await createTenant("life-removed", "growth");
    const other = await createTenant("life-removed-other", "growth");
    const leaver = tenant.userIds.member;

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: leaver,
      kind: "issue_assigned",
      inApp: true,
      email: true,
      digestOnly: true,
    });
    await memberRepo.insertMember(other.org.id, leaver, "member", null);

    const now = new Date(Date.now() + 30 * DAY_MS).toISOString();
    for (const hash of ["s-here", "s-there", "s-none"]) {
      await sessionRepo.createSession(leaver, hash, now as never);
    }
    const setOrg = (hash: string, orgId: string | null) =>
      getDb()
        .update(sessions)
        .set({ activeOrgId: orgId })
        .where(eq(sessions.tokenHash, hash))
        .run();
    setOrg("s-here", tenant.org.id);
    setOrg("s-there", other.org.id);

    await expect(listDigestRecipients(tenant.org.id)).resolves.toContain(leaver);

    const row = await memberRepo.findMember(tenant.org.id, leaver);
    if (!row) throw new Error("missing member");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: row.id,
    });

    const payload = { title: "t", body: "b", href: "/x", actorId: null };
    await expect(notify(tenant.org.id, "issue_assigned", [leaver], payload)).resolves.toHaveLength(0);
    await expect(listDigestRecipients(tenant.org.id)).resolves.not.toContain(leaver);

    const activeOrg = async (hash: string) =>
      (await sessionRepo.findSessionByTokenHash(hash))?.activeOrgId ?? null;
    await expect(activeOrg("s-here")).resolves.toBeNull();
    await expect(activeOrg("s-there")).resolves.toBe(other.org.id);

    // Rejoining restores notifications.
    const { token } = await inviteWithToken(tenant, `member@life-removed.test`);
    await invitationService.acceptInvitation(leaver, { token });
    await expect(notify(tenant.org.id, "issue_assigned", [leaver], payload)).resolves.toHaveLength(1);
    await expect(listDigestRecipients(tenant.org.id)).resolves.toContain(leaver);
  });

  it("stops every session defaulting to a deleted workspace", async () => {
    const tenant = await createTenant("life-org-deleted", "growth");
    const other = await createTenant("life-org-kept", "growth");
    const expiry = new Date(Date.now() + 30 * DAY_MS).toISOString();

    await sessionRepo.createSession(tenant.userIds.owner, "d-owner", expiry as never);
    await sessionRepo.createSession(tenant.userIds.admin, "d-admin", expiry as never);
    await sessionRepo.createSession(other.userIds.owner, "d-other", expiry as never);
    for (const [hash, orgId] of [
      ["d-owner", tenant.org.id],
      ["d-admin", tenant.org.id],
      ["d-other", other.org.id],
    ] as const) {
      getDb().update(sessions).set({ activeOrgId: orgId }).where(eq(sessions.tokenHash, hash)).run();
    }

    await organizationService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const activeOrg = async (hash: string) =>
      (await sessionRepo.findSessionByTokenHash(hash))?.activeOrgId ?? null;
    await expect(activeOrg("d-owner")).resolves.toBeNull();
    await expect(activeOrg("d-admin")).resolves.toBeNull();
    await expect(activeOrg("d-other")).resolves.toBe(other.org.id);

    // listNotifications stays reachable for the surviving org.
    await expect(
      listNotifications(other.actors.owner, {
        orgId: other.org.id,
        recipientId: other.userIds.owner,
        unreadOnly: false,
        limit: 5,
        cursor: null,
      }),
    ).resolves.toBeDefined();
  });
});

